        yield* requireStudent(ctx, input.student_id);
        const g2 = yield ctx.store.get("Guardians", input.guardian_id);
        if (!g2) throw notFound("guardian");
        const links = yield ctx.store.findBy("StudentGuardians", "student_id", input.student_id);
        if (links.some((l) => l.guardian_id === g2.id && l.status === "ACTIVE" && dateInRange(input.effective_from, l.effective_from, l.effective_to))) {
          throw new AppError("UNIQUE_VIOLATION", "already linked", { messageTh: "ผูกผู้ปกครองคนนี้กับนักเรียนแล้ว" });
        }
        const cs = ctx.changeSet();
        if (input.is_primary_contact) {
          for (const l of links.filter((x) => x.status === "ACTIVE" && x.is_primary_contact)) cs.update("StudentGuardians", l, { is_primary_contact: false });
        }
        const link = cs.insert("StudentGuardians", {
          student_id: input.student_id,
          guardian_id: g2.id,
          relationship: input.relationship,
          relationship_note: input.relationship_note,
          is_primary_contact: input.is_primary_contact,
          contact_priority: input.contact_priority,
          permitted_actions: input.permitted_actions || DEFAULT_GUARDIAN_PERMISSIONS,
          notification_preferences: input.notification_preferences || DEFAULT_NOTIFICATION_PREFS,
          status: "ACTIVE",
          verified_by: ctx.principal.user_id,
          verified_at: ctx.now,
          verification_method: input.verification_method,
          effective_from: input.effective_from,
          effective_to: null
        });
        cs.audit({ action: "guardian.link", entityType: "StudentGuardians", entityId: link.id, studentId: input.student_id, after: { guardian_id: g2.id, relationship: input.relationship, permitted_actions: link.permitted_actions, verification_method: input.verification_method } });
